sys_script_client.script:
function onSubmit() {
	var gaVerifySchedules = new GlideAjax('verifySchedules');
	gaVerifySchedules.addParam('sysparm_name', 'verifySchedules'); 
	gaVerifySchedules.addParam('sysparm_date', g_form.getValue("date")); 
	gaVerifySchedules.addParam('sysparm_course', g_form.getValue("course")); 

	//var result = gaVerifySchedules.getXMLAnswer(ScheduleParse);
	var result = gaVerifySchedules.getXMLWait();
	alert(result);

	return false;

}

// callback function for returning the result from the script include
function ScheduleParse(response) {
	var result = response;

	if (result){
		g_form.addErrorMessage('Já existe registro para essa data.');
		return false;
	} else {
		return true;
	}
}
